-- Cité Scolaire Ambouli — Users, Staff, Enseignants, RH, Paie

-- Nettoyage
DELETE FROM "bulletins_paie" WHERE "ficheRHId" IN (SELECT e."id" FROM "fiches_rh" e WHERE e."tenantId"='tenant-ambouli');
DELETE FROM "fiches_rh" WHERE "tenantId"='tenant-ambouli';
DELETE FROM "enseignant_sites" WHERE "enseignantId" IN (SELECT id FROM "enseignants" WHERE "tenantId"='tenant-ambouli');
DELETE FROM "enseignants" WHERE "tenantId"='tenant-ambouli';
DELETE FROM "user_sites" WHERE "userId" IN (SELECT id FROM "users" WHERE "tenantId"='tenant-ambouli' AND "id" != 'user-admin-amb');
DELETE FROM "users" WHERE "tenantId"='tenant-ambouli' AND "id" != 'user-admin-amb';

